            unique_words.add(line.strip())

    with open("temp_unique.txt", "w") as f5:
        for u_word in unique_words:
            f5.write(u_word + "\n")

    current_word_index = 0
    while current_word_index < len(processed_words):
        word_to_count = processed_words[current_word_index]
        count = 0
        with open("temp_processed.txt", "r") as f6:
            for line in f6:
                if line.strip() == word_to_count:
                    count += 1
        freq[word_to_count] = count
        current_word_index += 1

    with open("temp_frequencies.txt", "w") as f7:
        for word, count in freq.items():
            f7.write(f"{word}:{count}\n")

    final_freq = {}
    with open("temp_frequencies.txt", "r") as f8:
        for line in f8:
            word, count_str = line.strip().split(':')
            final_freq[word] = int(count_str)

    return final_freq

